    visited = [[False] * m for _ in range(n)]
    to_remove = set()
    dx, dy = [0, 0, 1, -1], [1, -1, 0, 0]

    def bfs(start_pos):
        stack = [start_pos]
        visited[start_pos] = True
        room_x = [start_pos[0]]
        room_y = [start_pos[1]]
        while stack:
            x, y = stack.pop()
            for nd in range(4):
                ndx, ndy = dx[nd], dy[nd]
                ncx,ncy = x+ndx, y+ndy
                if 0 <= ncx < n and 0 <= ncy < m:
                    if grid[ncx][ncy] == '.' and not visited[ncy][ncx]:
                        visited[ncy][ncx] = True
                        visited[y][x] = True
                        stack.append((n, m))
                    elif grid[ncx][ncy] == '*':
                        to_remove.add((ncx, ncy))
        return visited

    for x in range(n):
        for y in range(m):
            if grid[x][y] == '.' and not visited[x][y]:
                room_cells = []
                stack = [(x, y)]
                visited[x][y] = True
                room_cells.append((x, y))
                min_x, max_x, min_y, max_y = x, x, y, y
                while stack:
                    rx, ry = stack.pop()
                    for nd in range(4):
                        ndx, ndy = dx[nd], dy[nd]
                        ncx, ncy = rx+ndx, ry+ndy
