                            if grid[ncx][ncy] == '.' and not visited[ncy][ncx]:
                                visited[ncy][ncx] = True
                                room_cells.append((ncx, ncy))
                                min_x = min(min_x, ncx)
                                max_x = max(max_x, ncx)
                                min_y = min(min_y, ncy)
                                max_y = max(max_y, ncy)
                            elif grid[ncx][ncy] == '*' and (ncx, ncy) not in to_remove:
                                to_remove.add((ncx, ncy))

                for cx in range(min_x, max_x + 1):
                    for cy in range(min_y, max_y + 1):
                        if (cx, cy) != (x, y):
                            if not visited[cy][cx]:
                                stack.append((cx, cy))
                                visited[cy][xcx] = True
                                room_cells.append((cx, cy))
                for cx in range(min_x, max_x + 1):
                    for cy in range(min_y, max_y + 1):
                        if (cx, cy) not in room_cells:
                            to_remove.add((cx, cy))
                            if 0 <= cx < n and 0 <= cy < m:
                                grid[cy][cx] = '.'

    return '\n'.join(''.join(row) for row in grid)

