def solution(input_str):
    """Main solution function"""
    lines = input_str.strip().split('\n')
    if len(lines) < 5:
        return "-1"

    vowel_str = lines[0]
    n, m = map(int, lines[1].split())
    rules = []
    for i in range(2, 2 + m):
        parts = lines[i].split()
        pos1, t1, pos2, t2 = parts[0], parts[1], parts[2], parts[3]
        pos1, pos2 = int(pos1), int(pos2)
        rules.append((pos1, t1, pos2, t2))
    s = lines[2 + m].strip()

    l = len(vowel_str)
    first_l = [chr(97 + i) for i in range(l)]

    vowels = set(c for c in first_l if vowel_str[ord(c) - ord('a')] == 'V')
    consonants = set(c for c in first_l if c not in vowels)

    def can_place(pos, char):
        """Check if placing char at position pos (1-indexed) violates rules"""
        s_char_is_vowel = char in vowels

        for pos1, t1, pos2, t2 in rules:
            if pos1 == pos:
                if t1 == 'V' and not s_char_is_vowel:
                    return False
                if t1 == 'C' and s_char_is_vowel:
                    return False

        return True

    def check_full(word, rules, vowels, consonants):
        """Check if a complete word satisfies all rules"""
        for pos1, t1, pos2, t2 in rules:
            s1 = word[pos1 - 1]
            s2 = word[pos2 - 1]

            s1_is_v = s1 in vowels
            s2_is_v = s2 in vowels

            if t1 == 'V':
                if not s1_is_v:
                    return False
                if t2 == 'V':
                    if not s2_is_v:
                        return False
                else:  # t2 == 'C'
                    if s2_is_v:
                        return False
            else:  # t1 == 'C'
                if s1_is_v:
                    return False
                if t2 == 'V':
                    if not s2_is_v:
                        return False
                else:  # t2 == 'C'
                    if s2_is_v:
                        return False
        return True

    # Try to find the smallest valid word >= s
    best_result = None

    def backtrack(pos, current):
        nonlocal best_result
        if best_result is not None:
            return

        if pos == n:
            if check_full(current, rules, vowels, consonants):
                result = ''.join(current)
                if best_result is None or result < best_result:
                    best_result = result
            return

        # Determine starting character
        if current == s[:pos-1]:
            start_idx = list(first_l).index(s[pos - 1])
            for i in range(start_idx, l):
                char = first_l[i]
                if not can_place(pos, char):
                    continue

                current.append(char)
                backtrack(pos + 1, current)
                current.pop()

                if best_result is not None:
                    return
                break
        else:
            start_idx = 0
            for i in range(l):
                char = first_l[i]
                if not can_place(pos, char):
                    continue

                current.append(char)
                backtrack(pos + 1, current)
                current.pop()

                if best_result is not None:
                    return
                break

    # We need to find words starting from each prefix up to some position
    # where we go above s

    # Strategy: try all prefixes of s, then go higher at some position
    for split_pos in range(n):  # split_pos: length of prefix matching s
        current = list(s[:split_pos])
        if check_full(current, rules, vowels, consonants):
            # Try to complete with larger characters
            backtrack(split_pos + 1, current)
            if best_result is not None:
                return best_result

        # Try going higher at this position
        if split_pos < n:
            start_char = s[split_pos]
            for i in range(list(first_l).index(start_char) + 1, l):
                current = list(s[:split_pos])
                char = first_l[i]
                if not can_place(split_pos + 1, char):
                    continue

                current.append(char)
                backtrack(split_pos + 2, current)
                if best_result is not None:
                    return best_result
                current.pop()

    return best_result if best_result is not None else "-1"

