    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    pairs = []
    for i in range(m):
        u, v = map(int, lines[2 + i].split())
        pairs.append((u - 1, v - 1))

    from collections import defaultdict

    def get_prime_factors(num):
        factors = defaultdict(int)
        d = 2
        while d * d <= num and num > 1:
            while num % d == 0:
                factors[d] += 1
                num //= d
            d += 1
        if num > 1:
            factors[num] += 1
        return factors

    # Count prime factors for each position
    prime_counts = defaultdict(lambda: defaultdict(int))

    for i in range(n):
        factors = get_prime_factors(a[i])
        for p, count in factors.items():
            prime_counts[p][i] = count

    # Get all primes
    all_primes = set()
    for i in range(n):
        all_primes.update(prime_counts[i].keys())
    all_primes = set(p for p in all_primes if any(prime_counts[p][i] > 0 for i in range(n)))

    total_ops = 0
    from collections import deque

    INF = float('inf')

    def dinic(source, sink, n_nodes, capacities):
        """Dinic's algorithm for max flow"""
        level = [-1] * n_nodes
        ptr = [0] * n_nodes

        def bfs():
            nonlocal level
            for i in range(n_nodes):
                level[i] = -1
            level[source] = 0
            queue = deque([source])
            while queue:
                u = queue.popleft()
                if u == sink:
                    return True
                for v in range(n_nodes):
                    if capacities[u][v] > 0 and level[v] == -1:
                        level[v] = level[u] + 1
                        queue.append(v)
            return level[sink] != -1

        def dfs(u, flow):
            if u == sink or flow == 0:
                return flow
            for v in range(ptr[u], n_nodes):
                if level[u] + 1 == level[v] and capacities[u][v] > 0:
                    pushed = dfs(v, min(flow, capacities[u][v]))
                    if pushed > 0:
                        capacities[u][v] -= pushed
                        capacities[v][u] += pushed
                        return pushed
                ptr[u] += 1
            return 0

        max_flow = 0
        while bfs():
            ptr = [0] * n_nodes
            while True:
                pushed = dfs(source, INF)
                if pushed == 0:
                    break
                max_flow += pushed
        return max_flow

    for p in all_primes:
        source = 0
        sink = n + 1
        num_nodes = n + 2

        # Build capacity matrix
        capacities = [[0] * num_nodes for _ in range(num_nodes)]

        # Source to odd-indexed (0-indexed even) positions
        for i in range(n):
            if i % 2 == 0:  # Original index was odd
                count = prime_counts[p][i]
                if count > 0:
                    capacities[source][i] = count

        # Even-indexed (0-indexed odd) positions to sink
        for i in range(n):
            if i % 2 == 1:  # Original index was even
                count = prime_counts[p][i]
                if count > 0:
                    capacities[i][sink] = count

        # Add pair edges from odd positions to even positions
        for u, v in pairs:
            # Check which position is original odd (0-indexed even) and which is original even
            u_is_odd = (u % 2 == 0)
            v_is_odd = (v % 2 == 0)

            # Only add edge from original odd to original even
            if u_is_odd and not v_is_odd:
                capacities[u][v] = INF
            elif not u_is_odd and v_is_odd:
                capacities[v][u] = INF

        # Run Dinic's algorithm
        flow = dinic(source, sink, num_nodes, capacities)
        total_ops += flow

    return str(total_ops) + '\n'

