def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    arr = list(map(int, lines[1].split()))

    # Find positions that are -1 (1-indexed)
    missing_positions = []
    for i in range(n):
        if arr[i] == -1:
            missing_positions.append(i + 1)  # Convert to 1-indexed

    # Find which values are used in the permutation
    used_values = set()
    for val in arr:
        if val != -1:
            used_values.add(val)

    # Find missing values (values from 1 to n that don't appear)
    missing_values = set(range(1, n + 1)) - used_values

    # S is the set of "dangerous" positions where position number equals a missing value
    # For these positions, we cannot assign value == position
    dangerous_positions = [pos for pos in missing_positions if pos in missing_values]

    k = len(missing_positions)      # Number of positions to fill
    s_size = len(dangerous_positions)  # Number of dangerous positions

    MOD = 1000000007

    # Precompute factorials
    fact = [1] * (k + 1)
    for i in range(2, k + 1):
        fact[i] = (fact[i - 1] * i) % MOD

    # Modular exponentiation and inverse
    def power(a, b, m):
        result = 1
        a = a % m
        while b > 0:
            if b % 2 == 1:
                result = (result * a) % m
            a = (a * a) % m
            b //= 2
        return result

    def modInverse(n, m):
        return power(n, m - 2, m)

    # nCr modulo MOD
    def nCr_mod(n, r, mod):
        if r < 0 or r > n:
            return 0
        num = 1
        den = 1
        for i in range(r):
            num = (num * (n - i)) % mod
            den = (den * (i + 1)) % mod
        return (num * modInverse(den, mod)) % mod

    # Inclusion-Exclusion Principle
    # We count assignments avoiding dangerous positions getting their own value
    ans = 0
    for j in range(s_size + 1):
        # j positions get their own value (forbidden in a valid solution)
        term = nCr_mod(s_size, j, MOD) * fact[k - j]
        term %= MOD
        if j % 2 == 1:
            ans = (ans - term) % MOD
        else:
            ans = (ans + term) % MOD

    return str((ans + MOD) % MOD)

