                if val < row_min_val:
                    row_min_val = val
                    row_min_col = c

        if row_min_val < best_val:
            best_val = row_min_val
            best_col = row_min_col
            min_row = mid_row

        # If we found a smaller value in row mid_row, the global minimum
        # might be in rows above or after
        if mid_row == 1:
            # Check remaining rows
            for r in range(2, n + 1):
                col_check = best_col
                val = interactive.query(r, col_check)
                if val < best_val:
                    best_val = val
                    min_row = r
        elif mid_row == n:
            break
        else:
            # Update search range based on monotonic property
            if left_row < mid_row:
                left_row = mid_row + 1
            right_row = mid_row

    # Final check - verify we have the minimum
    # Query a few cells around best_col in min_row again for confirmation
    for offset in [0, -1, 1]:
        c = best_col + offset
        if 1 <= c <= m and c != best_col:
