    n = int(lines[0])
    intervals = []
    for i in range(1, n + 1):
        l, r = map(int, lines[i].split())
        intervals.append((i, l, r))

    def overlaps(i, j):
        l1, r1 = intervals[i-1][1], intervals[i-1][2]
        l2, r2 = intervals[j-1][1], intervals[j-1][2]
        return max(l1, l2) <= min(r1, r2)

    result = []
    visited = [False] * (n + 1)

    for i in range(1, n + 1):
        if not visited[i]:
            component = []
            stack = [i]
            visited[i] = True
            while stack:
                node = stack.pop()
                component.append(node)
                for j in range(1, n + 1):
                    if not visited[j] and overlaps(node, j):
                        visited[j] = True
                        stack.append(j)
            component.sort(key=lambda x: intervals[x-1][1])
            result.extend(component)

