    lines = input_data.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    adj = [[] for _ in range(n + 1)]

    for i in range(1, m + 1):
        v, u = map(int, lines[i].split())
        adj[v].append(u)
        adj[u].append(v)

    # DFS to find cycles
    visited = [False] * (n + 1)
    parent = {}
    depth = {}
    cycles = []
    used_rep = set()

    def dfs(u, p, d):
        visited[u] = True
        parent[u] = p
        depth[u] = d

        for v in adj[u]:
            if v == p:
                continue
            if visited[v]:
                if depth[v] < depth[u]:  # Back edge to ancestor
                    # Cycle found via back edge (u, v)
                    cycle = []
                    curr = u
                    while curr != v:
                        cycle.append(curr)
                        curr = parent[curr]
                    cycle.append(v)
                    cycle.append(u)  # Complete circle

                    # Check if cycle length is valid
                    # Remove duplicate u at end for length check
                    actual_cycle = cycle[:-1]

                    if len(actual_cycle) >= 3 and len(actual_cycle) % 3 != 0:
                        if u not in used_rep:
                            used_rep.add(u)
                            cycles.append(actual_cycle)
            else:
                dfs(v, u, d + 1)

    # Explore all connected components
    for start in range(1, n + 1):
        if not visited[start]:
            dfs(start, -1, 0)
            if len(cycles) >= k:
                break

    # If we found enough cycles
    if len(cycles) >= k:
        output = ["CYCLES"]
        for cycle in cycles[:k]:
            output.append(str(len(cycle)))
            output.append(" ".join(map(str, cycle)))
        return "\n".join(output)
    else:
        # Try to find a long simple path
        visited_path = [False] * (n + 1)
        path = []
        found_path = False

        def find_path(u):
            nonlocal found_path
            path.append(u)
            visited_path[u] = True

            if len(path) >= n // k:
                # Check if it's a simple path
                if len(set(path)) == len(path):
                    found_path = True
                    return True

            for v in adj[u]:
                if not visited_path[v]:
                    if find_path(v):
                        return True

            path.pop()
            visited_path[u] = False
            return False

        find_path(1)

        if found_path:
            output = ["PATH"]
            output.append(str(len(path)))
            output.append(" ".join(map(str, path)))
            return "\n".join(output)

    return "-1"

