    if not input_str:
        return "-1"

    parts = input_str.split('\n')
    line = parts[0]

    if not line:
        return "-1"

    try:
        data = line.split()
        if not data:
            return "-1"

        maxx = int(data[0])
        maxy = int(data[1])
        w = int(data[2])
    except:
        return "-1"

    if maxy == 0 or maxx == 0:
        return "-1"

    if w == 1:
        return "1 1"

    # Try small x and y values first
    def count_lucky(x, y, max_a=x, max_b=y):
        """Count lucky tickets in range [1,x] x [1,y]"""
        count = 0
        for a in range(1, x + 1):
            for b in range(1, y + 1):
                if a * b == int(str(a)[::-1]) * int(str(b)[::-1]):
                    count += 1
        return count

    # Greedy search: try to find minimum x * y
    result_x = None
    result_y = None
    best_product = float('inf')

    # Limit search space
    if maxx < 100:
        search_maxx = maxx
        search_maxy = maxy
    else:
        search_maxx = min(maxx, 200)
        search_maxy = min(maxy, 200)
        if search_maxx * search_maxy <= 10000:
            # More comprehensive search
            search_maxx = maxx
            search_maxy = maxy

    # Find valid combinations
    for x in range(1, search_maxx + 1):
        for y in range(1, search_maxy + 1):
            if x * y >= best_product:
                break
            if x > maxx or y > maxy:
                break

            if count_lucky(x, y, x, y) >= w:
                if x * y < best_product:
                    best_product = x * y
                    result_x = x
                    result_y = y

    # Try more systematically for larger inputs
    if result_x is None and maxx * maxy < 100000:
        for x in range(1, maxx + 1):
            for y in range(1, maxy + 1):
                if x * y >= best_product:
                    break
                if count_lucky(x, y, x, y) >= w:
                    if x * y < best_product:
                        best_product = x * y
                        result_x = x
                        result_y = y

    if result_x is None:
        return "-1"

    return f"{result_x} {result_y}\n"

