def count_factor_2(n):
    """Count the number of times 2 divides n"""
    count = 0
    while n > 0 and n % 2 == 0:
        n //= 2
        count += 1
    return count

def count_factor_5(n):
    """Count the number of times 5 divides n"""
    count = 0
    while n > 0 and n % 5 == 0:
        n //= 5
        count += 1
    return count

