from functools import lru_cache

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    strengths = list(map(int, lines[1].split()))
    m = int(lines[2])
    actions = []
    for i in range(m):
        parts = lines[3 + i].split()
        actions.append((parts[0], int(parts[1])))

    @lru_cache(None)
    def solve(idx, mask):
        if idx == m:
            return 0

        action_type = actions[idx][0]
        team = actions[idx][1]

        if action_type == 'p':
            # Pick mode
            best = float('-inf')
            for i in range(n):
                if not (mask & (1 << i)):
                    # Hero i is available
                    new_mask = mask | (1 << i)
                    if team == 1:
                        # Team 1 picks, adds to their score (positive for Team1 - Team2)
                        result = strengths[i] + solve(idx + 1, new_mask)
                        best = max(best, result)
                    else:
                        # Team 2 picks, adds to their score (negative for Team1 - Team2)
                        result = -strengths[i] + solve(idx + 1, new_mask)
                        best = min(best, result)
            return best
        else:
            # Ban mode
            best = float('-inf')
            for i in range(n):
                if not (mask & (1 << i)):
                    # Hero i is available to ban
                    new_mask = mask | (1 << i)
                    result = solve(idx + 1, new_mask)
                    if team == 1:
                        best = max(best, result)
                    else:
                        best = min(best, result)
            return best

    return str(solve(0, 0)) + '\n'

