def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = []
    for i in range(1, len(lines)):
        part = list(map(int, lines[i].split()))
        a.extend(part)
    a = a[:n]

    MOD = 10**9 + 7

    def get_sq_free(x):
        result = 1
        d = 2
        while d * d <= x:
            count = 0
            while x % d == 0:
                x //= d
                count += 1
            if count % 2 == 1:
                result *= d
            d += 1
        if x > 1:
            result *= x
        return result

    groups = defaultdict(list)
    for num in a:
        groups[get_sq_free(num)].append(num)

    group_sizes = [len(g) for g in groups.values()]

    total = sum(group_sizes)

    fact = [1] * (total + 1)
    inv = [1] * (total + 1)

    for i in range(1, total + 1):
        fact[i] = (fact[i - 1] * i) % MOD

    inv[total] = pow(fact[total], MOD - 2, MOD)
    for i in range(total - 1, -1, -1):
        inv[i] = (inv[i + 1] * (i + 1)) % MOD

    def C(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * inv[k] % MOD * inv[n - k] % MOD

    dp = [0] * (total + 1)
    dp[0] = 1

    for g_size in group_sizes:
        new_dp = [0] * (total + 1)
        for prev in range(total + 1):
            if dp[prev] == 0:
                continue
            if prev == 0:
                ways = 1
            else:
                ways = C(prev + 1 - 1, g_size)
            for same_pos in range(g_size + 1):
                if g_size == 0:
                    result = dp[prev]
                elif same_pos == 0:
                    result = dp[prev] * C(prev, 0)
                else:
                    q = g_size - same_pos
                    r = prev - same_pos + g_size
                    if q > r or q < 0:
                        result = 0
                    else:
                        result = dp[prev] * C(r, q) if r >= q else 0
                new_dp[prev + g_size - same_pos] = (new_dp[prev + g_size - same_pos] + result * ways) % MOD

        dp = new_dp

    result = sum(dp) % MOD
    return str(result)

