def popcount(n):
    return bin(n).count('1')

def solve(m, t, s, a):
    MOD = 1051131

    # Extend a to 2m islands using the formula
    n = 2 * m
    for i in range(s, n):
        a.append((101 * a[i - s - 1] + 10007) % MOD)

    # Build transition matrix (adjacency matrix including staying)
    # Size: 2m x 2m (indices 0 to 2m-1, corresponding to islands 1 to 2m)
    N = n
    T = [[0] * N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            if i == j:
                T[i][j] = 1  # staying
            else:
                bridges = 1 << popcount(i & j)
                T[i][j] = bridges % MOD

    # Matrix exponentiation: T^t
    def mat_mul(A, B):
        C = [[0] * N for _ in range(N)]
        for i in range(N):
            for k in range(N):
                if A[i][k] == 0:
                    continue
                for j in range(N):
                    C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
        return C

    def mat_pow(A, p):
        if p == 0:
            return [[0] * N for i in range(N)]
        result = [[0] * N for _ in range(N)]
        for i in range(N):
            result[i][i] = 1
        base = [A[i][:] for i in range(N)]
        while p > 0:
            if p & 1:
                result = mat_mul(result, base)
            base = mat_mul(base, base)
            p >>= 1
        return result

    T_t = mat_pow(T, t)

    # Compute ans[i] = sum_j (a[j] * T_t[j][i])
    # Note: a[j] corresponds to T_t[0..][j], so we sum a[j] * T_t[j][i]

    ans = []
    for i in range(N):
        total = 0
        for j in range(N):
            total = (total + a[j] * T_t[j][i]) % MOD
        ans.append(total)

    # Output XOR sum
    xor_sum = 0
    for x in ans:
        xor_sum ^= x
    return xor_sum

