import sys

def get_divisors(k):
    """Get all divisors of k."""
    divs = set()
    for i in range(1, int(k**0.5) + 1):
        if k % i == 0:
            divs.add(i)
            divs.add(k // i)
    return sorted(list(divs))

def check_all_rectangles_equal(matrix, r, c, n, m):
    """
    Check if all r×c non-overlapping rectangles are pairwise equal.
    """
    num_rows = n // r
    num_cols = m // c

    baseline = None

    for i in range(num_rows):
        for j in range(num_cols):
            # Extract this rectangle
            rect = []
            for si in range(r):
                row = []
                for sj in range(c):
                    row.append(matrix[i * r + si][j * c + sj])
                rect.append(row)
            rect = tuple(tuple(row) for row in rect)

            if baseline is None:
                baseline = rect
                if not (i == 0 and j == 0):
                    return False
            else:
                if rect != baseline:
                    return False

    return True

