def solve_match(a, b):
    """Find the best possible score for a match given total points a and b"""

    # Check for impossibility quickly
    min_possible_points_for_win = 25 * 3 + 15 * 0  # Alice wins 3 sets right away
    if a < min_possible_points_for_win and b < min_possible_points_for_win:
        return "Impossible"

    # Use DFS to find valid configurations
    result = dfs(0, 0, 0, [(0, 0)], a, b)
    if result:
        return result
    return "Impossible"

def dfs(set_idx, alice_wins, bob_wins, sets, rem_a, rem_b):
    """Depth-first search for valid set configurations"""

    if rem_a == 0 and rem_b == 0:
        alice_final = alice_wins
        bob_final = bob_wins
        if alice_final >= 3:
            return f"{alice_final}:{bob_final}\n" + " ".join(f"{sa}:{sb}" for sa, sb in sets)
        return None

    if set_idx >= 5:
        return None

    # Try various score combinations
    lower = 24 if set_idx < 5 else 14

    for wa in range(lower, min(rem_a + 1, 201)):
        for wb in range(lower, min(rem_b + 1, 201)):
            # Check validity
            if wa >= 25:
                valid = (wa - wb >= 2) and set_idx < 5 or (wb < 25 and wa >= 25)
            elif wb >= 25:
                valid = (wb - wa >= 2) and set_idx < 5 or (wa < 25 and wb >= 25)
            else:
                continue

            if is_valid_set(wa, wb, set_idx + 1):
                # Determine who won this set
                alice_won = wa > wb

                new_alice = alice_wins + alice_won
                new_bob = bob_wins + (1 if not alice_won else 0)
                if new_alice >= 3 and new_bob >= 3:
                    continue

                result = dfs(set_idx + 1, new_alice, new_bob, sets + [(wa, wb)], rem_a - wa, rem_b - wb)
                if result:
                    return result

    return None

def is_valid_set(wa, wb, set_num):
    """Check if this set score is valid"""
    if set_num <= 4:  # First 4 sets
        if min(wa, wb) < 24:
            return False
        diff = wa - wb
        if wa >= 25 and diff >= 2 or wb >= 25 and -diff >= 2:
            return True
        return False
    else:  # 5th set
        if min(wa, wb) < 14:
            return False
        diff = wa - wb
        if wa >= 15 and diff >= 2 or wb >= 15 and -diff >= 2:
            return True
        return False

