def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def solution(input_str):
    lines = input_str.strip().split('\n')
    idx = 0

    n, m = map(int, lines[idx].split())
    idx += 1

    graph = [[] for _ in range(n + 1)]
    for _ in range(m):
        a, b, l = map(int, lines[idx].split())
        idx += 1
        graph[a].append((b, l))

    # Tarjan's algorithm for SCCs
    disc = [-1] * (n + 1)
    low = [-1] * (n + 1)
    on_stack = [False] * (n + 1)
    stack = []
    timer = 0
    scc_id = [-1] * (n + 1)
    scc_count = 0

    def tarjan_dfs(u):
        nonlocal timer, scc_count
        disc[u] = low[u] = timer
        timer += 1
        stack.append(u)
        on_stack[u] = True

        for v, _ in graph[u]:
            if disc[v] == -1:
                tarjan_dfs(v)
                low[u] = min(low[u], low[v])
            elif on_stack[v]:
                low[u] = min(low[u], disc[v])

        if low[u] == disc[u]:
            scc_count += 1
            while True:
                v = stack.pop()
                on_stack[v] = False
                scc_id[v] = scc_count
                if v == u:
                    break

    for i in range(1, n + 1):
        if disc[i] == -1:
            tarjan_dfs(i)

    # For each SCC, compute the GCD of all cycle lengths
    # We start from each node and use DFS to find cycles
    scc_gcd = {}

    for start_node in range(1, n + 1):
        scc = scc_id[start_node]
        if scc in scc_gcd:
            continue

        # BFS to compute distances from start_node within this SCC
        dist = {start_node: 0}
        queue = [start_node]
        head = 0
        while head < len(queue):
            u = queue[head]
            head += 1
            for v, l in graph[u]:
                if scc_id[v] == scc and v not in dist:
                    dist[v] = dist[u] + l
                    queue.append(v)

        # DFS to find back edges and compute GCD of cycle lengths
        g = float('inf')
        visited = set()
        current_path = set()

        def dfs(u, d):
            nonlocal g
            visited.add(u)
            current_path.add(u)

            for v, l in graph[u]:
                if scc_id[v] == scc:
                    if v not in visited:
                        dfs(v, d + l)
                    elif v in current_path:
                        # Found a back edge forming a cycle
                        cycle_len = d - dist[v]
                        g = gcd(g, cycle_len)

            visited.remove(u)
            current_path.remove(u)

        dfs(start_node, dist[start_node])

        if g == float('inf'):
            scc_gcd[scc] = 0
        else:
            scc_gcd[scc] = int(g)

    # Process queries
    q = int(lines[idx])
    idx += 1

    ans = []
    for _ in range(q):
        v, s, t = map(int, lines[idx].split())
        idx += 1

        scc = scc_id[v]
        g = scc_gcd.get(scc, 0)

        # Check if we can achieve odometer reading 0
        if s == 0:
            ans.append("YES")
        else:
            # We need to find if there exists path length L such that (s + L) % t == 0
            # L must be a multiple of g (the GCD of all reachable cycle lengths)
            # So (s + k*g) % t == 0 for some k, meaning s % gcd(g, t) == 0
            if g == 0:
                # No cycles, can only return to start if no distance traveled
                ans.append("NO")
            else:
                g_t = gcd(g, t)
                if s % g_t == 0:
                    ans.append("YES")
                else:
                    ans.append("NO")

    return '\n'.join(ans)

