        for attempt_str, expected_count in attempts:
            actual_count = 0
            for i in range(n):
                if candidate[i] == int(attempt_str[i]):
                    actual_count += 1
            if actual_count != expected_count:
                valid = False
                break

        if valid:
            result += 1

    return str(result)
